package research.orthrus.axiom.materialhost;

import net.minecraft.launchwrapper.IClassTransformer;
import java.util.*;

/** Observation-only callback. The native generated bytes are returned unchanged. */
public final class MaterialTraitReference implements IClassTransformer {
    private static final Map<ClassLoader,Integer> SCOPES=new IdentityHashMap<>();
    private static final List<Map<String,Object>> DEFINITIONS=new ArrayList<>();
    @Override public byte[] transform(String name,String transformedName,byte[] input) {
        if(input==null||!MaterialTraitLoaderHook.TARGET.equals(transformedName))return input;
        return MaterialTraitLoaderHook.apply(input,"research/orthrus/axiom/materialhost/MaterialTraitReference");
    }
    public static byte[] define(ClassLoader loader,String name,byte[] bytes) {
        var observer=new MaterialArgumentBytecode();observer.processBytecode(name,bytes);
        DEFINITIONS.add(Map.of("name",name,"definitionScope",SCOPES.computeIfAbsent(loader,k->SCOPES.size()+1),
            "bytecode",observer.observations().get(name),
            "methodOrderIndependentSha256",MaterialTraitLoaderHook.methodOrderIndependentSha256(bytes)));
        return bytes;
    }
    public static List<Map<String,Object>> observations() {return List.copyOf(DEFINITIONS);}
}
